"""Signature checks for the event requests Corvid Payments sends us."""

import base64
import hashlib
import hmac

SIGNATURE_HEADER = "corvid-signature"
EVENT_ID_HEADER = "corvid-event-id"
MAX_AGE = 300  # seconds a signing time may lie before now
MAX_AHEAD = 60  # seconds a signing time may lie after now
_HEX = frozenset("0123456789abcdef")


def _header(headers, name):
    for key, value in headers.items():
        if isinstance(key, str) and key.lower() == name and isinstance(value, str):
            return value
    return None


def _parse_signature(value):
    """Returns (t, [v2 signatures]) or None when the header does not parse."""
    times = []
    v2 = []
    for element in value.split(","):
        element = element.lstrip(" ")
        name, sep, val = element.partition("=")
        if not sep or not name:
            return None
        if name == "t":
            times.append(val)
        elif name == "v2":
            v2.append(val)
        # v1 and any other scheme name: ignored
    if len(times) != 1:
        return None
    t = times[0]
    if not (t.isascii() and t.isdigit()):
        return None
    return int(t), v2


def _key(secret):
    if not isinstance(secret, str) or not secret.startswith("whsec_"):
        return None
    try:
        return base64.b64decode(secret[len("whsec_"):].encode("ascii"), validate=True)
    except ValueError:
        return None


def verify(headers: dict[str, str], body: bytes, secrets: list[str], now: int) -> bool:
    """True when the request carries a valid Corvid signature, else False. Never raises.

    `headers` are the request headers, `body` the request body as received, `secrets` the
    signing secrets the receiver holds (`whsec_...`), `now` the current time in Unix seconds.
    """
    try:
        sig_header = _header(headers, SIGNATURE_HEADER)
        event_id = _header(headers, EVENT_ID_HEADER)
        if sig_header is None or event_id is None:
            return False
        parsed = _parse_signature(sig_header)
        if parsed is None:
            return False
        t, candidates = parsed
        if t < now - MAX_AGE or t > now + MAX_AHEAD:
            return False
        payload = b"v2:" + str(t).encode() + b":" + event_id.encode() + b":" + bytes(body)
        # The signed time is the `t` text as sent; digits only, so only leading zeros differ.
        payload = (b"v2:" + sig_header_t(sig_header) + b":" + event_id.encode() + b":" + bytes(body))
        ok = False
        for secret in secrets:
            key = _key(secret)
            if key is None:
                continue
            expected = hmac.new(key, payload, hashlib.sha256).hexdigest().encode()
            for cand in candidates:
                if hmac.compare_digest(expected, cand.encode("utf-8", "replace")):
                    ok = True
        return ok
    except Exception:
        return False


def sig_header_t(sig_header):
    for element in sig_header.split(","):
        name, _, val = element.lstrip(" ").partition("=")
        if name == "t":
            return val.encode()
    return b""
